package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UserinfoEncryptedResponseAlgVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property userinfo encrypted response alg of oauth client ")
  void test_userinfo_encrypted_response_alg_v_o_builder() {
    Assertions.assertFalse(
        UserinfoEncryptedResponseAlgVO.nullValue().getUserinfoEncryptedResponseAlg().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        UserinfoEncryptedResponseAlgVO.tryFrom(null).getUserinfoEncryptedResponseAlg().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        UserinfoEncryptedResponseAlgVO.from("one").getUserinfoEncryptedResponseAlg().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> UserinfoEncryptedResponseAlgVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]",
        UserinfoEncryptedResponseAlgVO.from("one").toString());
  }
}
